import json,html
from pathlib import Path
root=Path('/tmp/it-perf/followup-evidence')
s=json.loads((root/'summary.json').read_text())['followup.json']
labels=[('Site load, localhost','local.loadMs'),('50-page grid interactive, localhost','local.gridInteractiveMs'),('Open page, original Playwright timing','local.openMs'),('Open page, DOM click to state','local.domClickToStateMs'),('Warm service restart','startMs'),('Site load, 10 Mbps / 20 ms','network.loadMs'),('50-page grid, 10 Mbps / 20 ms','network.gridInteractiveMs'),('Republish existing page','cli.publishMs'),('it open','cli.openMs'),('it actions, empty','cli.actionsMs'),('it wait, 10 ms idle timeout','cli.waitTimeoutMs'),('it wait, action ready','cli.waitReadyMs')]
def fmt(x):return f'{x["median"]:.0f} <span>[{x["p25"]:.0f}–{x["p75"]:.0f}]</span>'
rows=''.join(f'<tr><td>{html.escape(label)}</td><td>{s["baseline"]["metrics"][key]["n"]}</td><td>{fmt(s["baseline"]["metrics"][key])}</td><td>{fmt(s["candidate"]["metrics"][key])}</td></tr>' for label,key in labels)
lo=min(s[x]['load']['1Minute']['min'] for x in s);hi=max(s[x]['load']['1Minute']['max'] for x in s)
cpu=' / '.join(f'{s[x]["cpuBusy"]["weightedPercent"]:.1f}%' for x in ['baseline','candidate'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>It performance follow-up</title><style>
*{box-sizing:border-box}body{margin:0;font:14px/1.45 var(--font-sans,system-ui);color:var(--foreground,#172332)}p{margin:0 0 16px}.caption{font-size:13px;color:var(--muted-foreground,#586675)}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:10px 8px;border-bottom:1px solid var(--border,#d7dee6);vertical-align:top}th{font-size:12px;color:var(--muted-foreground,#586675);font-weight:600}td:first-child,th:first-child{text-align:left;padding-left:0}td:last-child,th:last-child{padding-right:0}td span{color:var(--muted-foreground,#586675);white-space:nowrap;font-size:12px}td:nth-child(2){color:var(--muted-foreground,#586675);font-size:12px}.notes{margin-top:16px;color:var(--muted-foreground,#586675);font-size:12px}a{color:var(--accent-foreground,#1a7784)}details{margin-top:16px}summary{cursor:pointer;font-weight:600}details p{font-size:12px;margin:10px 0 0;color:var(--muted-foreground,#586675)}@media(max-width:500px){body{font-size:12px}th,td{padding:9px 5px}td span{display:block;font-size:10px}th{font-size:10px}}
</style><body><p><strong>Latest interleaved comparison</strong><br><span class="caption">Milliseconds, median [25th–75th percentile]. Lower is better.</span></p><table><thead><tr><th>Operation</th><th>n each</th><th>Baseline</th><th>Candidate</th></tr></thead><tbody>ROWS</tbody></table><p class="notes">12 alternating baseline/candidate pairs. Linux, Node 24.22.1, real backend, 50 pages, fresh browser caches. About 20 agents share the machine. One-minute load LOAD on 12 logical CPUs; whole-host CPU busy CPU for baseline / candidate.</p><details><summary>What the two page-opening measurements mean</summary><p>The original timing includes Playwright waiting before it clicks and polling after the page is ready. DOM click to state measures the actual captured click until the page receives runtime state. The original metric is retained for comparison. Grid interactivity requires 50 cards and a successful sort, rather than a paint measurement.</p><p>The candidate bundle is byte-for-byte unchanged from the original PR. The follow-up fixes the CSP test to inspect served text and investigates the reported regression. The controlled gzip/identity experiment found overlapping load and grid timings. Absolute times from the earlier, busier run are not additional product gains. All samples remain, including one candidate outlier of 2.89 seconds for restart and 3.29 seconds for grid readiness. No local speedup or tail-latency equivalence is claimed.</p></details></body></html>'''
page=page.replace('ROWS',rows).replace('LOAD',f'{lo:.2f}–{hi:.2f}').replace('busy CPU','busy '+cpu)
(root/'results.html').write_text(page)
